// Taslaktaki `DRAW` nesnesinin Dart karşılığı (docs/home_studio/index.html,
// docs/zibo_world_roadmap.md Faz 2). Her çizim (0,0) sol üst köşeden başlar,
// [c] eşyanın ana rengi (#RRGGBB). Kanepeler [p] = 'back' / 'front' ile
// Zibo'nun arkasında ve önünde kalan parçaları ayrı verir.
//
// Taslak değişirse bu dosya elle güncellenir; koordinatlar taslakla birebir.
// ignore_for_file: prefer_interpolation_to_compose_strings

import 'dart:math' as math;

import 'svg_kit.dart';

typedef FurnitureArt = String Function(SvgKit k, String c, String p);

String m(String c, double amt) => SvgKit.mix(c, amt);

/// Yatakların ortak gövdesi (başlık [head] + çarşaf, yastıklar, ayaklar).
String bedBase(SvgKit k, String head, String c) =>
    '''$head<rect x="40" y="400" width="26" height="30" rx="8" fill="${m(c, -.35)}"/><rect x="434" y="400" width="26" height="30" rx="8" fill="${m(c, -.35)}"/>'''
    '''<rect x="30" y="220" width="440" height="170" rx="30" fill="${k.grad('#FFFFFF', '#E3E8EE')}"/><rect x="20" y="376" width="460" height="32" rx="14" fill="${k.grad(m(c, .05), m(c, -.28))}"/>'''
    '''<rect x="70" y="170" width="160" height="80" rx="38" fill="${k.grad('#FFFFFF', '#DCE3EA')}"/><rect x="270" y="170" width="160" height="80" rx="38" fill="${k.grad('#FFFFFF', '#DCE3EA')}"/>''';

